using EventLensAI.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace EventLensAI.Infrastructure.Persistence.Configurations;
internal sealed class VenueTypeConfiguration:IEntityTypeConfiguration<VenueType>{static readonly string[]N=["Hotel","Convention Center","School","University","Outdoor","Restaurant","Stadium","Mall","Office","Other"];public void Configure(EntityTypeBuilder<VenueType>b){b.ToTable("venue_types");b.ConfigureBase();b.Property(x=>x.Name).HasMaxLength(120);b.Property(x=>x.Description).HasMaxLength(1000);b.HasIndex(x=>new{x.OrganizationId,x.Name}).IsUnique().HasFilter("[IsDeleted] = 0");b.HasOne(x=>x.Organization).WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.NoAction);b.HasData(N.Select((n,i)=>new{Id=Guid.Parse($"20000000-0000-0000-0000-{i+1:000000000000}"),OrganizationId=(Guid?)null,Name=n,Description=(string?)null,IsSystemType=true,IsActive=true,CreatedAt=new DateTime(2026,1,1,0,0,0,DateTimeKind.Utc),UpdatedAt=(DateTime?)null,CreatedBy=(Guid?)null,UpdatedBy=(Guid?)null,IsDeleted=false}));}}
internal sealed class ScheduleTypeConfiguration:IEntityTypeConfiguration<ScheduleType>{static readonly string[]N=["Ceremony","Session","Break","Photo Session","Entertainment","Registration","Meeting","Other"];public void Configure(EntityTypeBuilder<ScheduleType>b){b.ToTable("schedule_types");b.ConfigureBase();b.Property(x=>x.Name).HasMaxLength(120);b.Property(x=>x.Description).HasMaxLength(1000);b.HasIndex(x=>new{x.OrganizationId,x.Name}).IsUnique().HasFilter("[IsDeleted] = 0");b.HasOne(x=>x.Organization).WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.NoAction);b.HasData(N.Select((n,i)=>new{Id=Guid.Parse($"30000000-0000-0000-0000-{i+1:000000000000}"),OrganizationId=(Guid?)null,Name=n,Description=(string?)null,IsSystemType=true,IsActive=true,CreatedAt=new DateTime(2026,1,1,0,0,0,DateTimeKind.Utc),UpdatedAt=(DateTime?)null,CreatedBy=(Guid?)null,UpdatedBy=(Guid?)null,IsDeleted=false}));}}
internal sealed class VenueConfiguration:IEntityTypeConfiguration<Venue>{public void Configure(EntityTypeBuilder<Venue>b){b.ToTable("venues");b.ConfigureBase();b.Property(x=>x.Name).HasMaxLength(200);b.Property(x=>x.Description).HasMaxLength(2000);b.Property(x=>x.AddressLine).HasMaxLength(500);b.Property(x=>x.City).HasMaxLength(120);b.Property(x=>x.State).HasMaxLength(120);b.Property(x=>x.Country).HasMaxLength(120);b.Property(x=>x.PostalCode).HasMaxLength(30);b.Property(x=>x.Latitude).HasPrecision(9,6);b.Property(x=>x.Longitude).HasPrecision(9,6);b.Property(x=>x.MapProviderReference).HasMaxLength(500);b.Property(x=>x.ContactPerson).HasMaxLength(200);b.Property(x=>x.ContactPhone).HasMaxLength(50);b.Property(x=>x.ContactEmail).HasMaxLength(320);b.HasIndex(x=>x.EventId);b.HasIndex(x=>x.VenueTypeId);b.HasOne(x=>x.Event).WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.VenueType).WithMany().HasForeignKey(x=>x.VenueTypeId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class EventScheduleItemConfiguration:IEntityTypeConfiguration<EventScheduleItem>{public void Configure(EntityTypeBuilder<EventScheduleItem>b){b.ToTable("event_schedule_items");b.ConfigureBase();b.Property(x=>x.Title).HasMaxLength(200);b.Property(x=>x.Description).HasMaxLength(2000);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.HasIndex(x=>x.EventId);b.HasIndex(x=>x.StartDateTime);b.HasIndex(x=>x.VenueId);b.HasOne(x=>x.Event).WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.Venue).WithMany().HasForeignKey(x=>x.VenueId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.ScheduleType).WithMany().HasForeignKey(x=>x.ScheduleTypeId).OnDelete(DeleteBehavior.NoAction);}}
